<?php
declare(strict_types=1);
if (!defined('CWP_BOOT')) { http_response_code(404); exit; }
require_once CWP_CODE_ROOT.'/app/settings/database_schemas.php';
$schemaRows=database_schema_snapshot();$schemaSummary=database_schema_summary($schemaRows);
$schemaMigrations=database_schema_migrations();$schemaSelectable=array_filter($schemaRows,fn($row,$marker)=>isset($schemaMigrations[$marker])&&!in_array($row['state'],['current','unsupported'],true),ARRAY_FILTER_USE_BOTH);
