$schemaReview=null;$schemaReviewError=null;$reviewToken=is_string($_GET['database_review']??null)?$_GET['database_review']:'';$storedReview=$_SESSION['database_schema_review']??null;
if($reviewToken!==''&&is_array($storedReview)&&isset($storedReview['requested'],$storedReview['review_hash'])&&is_array($storedReview['requested'])&&is_string($storedReview['review_hash'])){
    try{$candidate=database_schema_plan($storedReview['requested'],$schemaRows);if(!hash_equals($reviewToken,$storedReview['review_hash'])||!hash_equals($candidate['review_hash'],$storedReview['review_hash']))throw new RuntimeException('Database state or selection changed.');$schemaReview=$candidate;}
