      <section class="workspace-card" data-database-selection><h2>Select database updates</h2><?php if($schemaSummary['blocking']):?><p>Selection is unavailable until unsupported feature versions are restored to a supported state.</p><?php elseif(!$schemaSelectable):?><p>No registered database update or optional setup is currently available.</p><?php else:?><p>Required updates and resumable interrupted work are selected by default. Optional feature storage remains off unless you explicitly select it.</p><form method="post"><?php admin_action('studio_database_plan');foreach($schemaSelectable as $marker=>$row)admin_check('database_updates[]',$row['label'].' — '.ucwords($row['state']).' ('.($row['installed']===''?'not prepared':$row['installed']).' → '.$row['current'].')',$row['needs_update'],$marker);?><button class="btn outline">Review selected updates →</button></form><?php endif;?></section>
